class Object
{
    // This is a simple wrapper around PyObject pointers to release them when this object goes
    // out of scope.  Note that it does *not* increment the reference count on acquisition but
    // it *does* decrement the count if you don't use Detach.
    //
    // It also does not have a copy constructor and doesn't try to manage passing pointers
    // around.  This is simply used to simplify functions by allowing early exits.

    Object(const Object& illegal) { }
    void operator=(const Object& illegal) { }

protected:
    PyObject* p;

public:
    Object(PyObject* _p = 0)
    {
        p = _p;
    }

    ~Object()
    {
        Py_XDECREF(p);
    }

    Object& operator=(PyObject* pNew)
    {
        Py_XDECREF(p);
        p = pNew;
        return *this;
    }

    bool IsValid() const { return p != 0; }

    bool Attach(PyObject* _p)
    {
        // Returns true if the new pointer is non-zero.

        Py_XDECREF(p);
        p = _p;
        return (_p != 0);
    }

    PyObject* Detach()
    {
        PyObject* pT = p;
        p = 0;
        return pT;
    }

    operator PyObject*()
    {
        return p;
    }

    operator PyTupleObject*()
    {
        // This is a bit weird.  I'm surprised the PyTuple_ functions and macros don't just use
        // PyObject.
        return (PyTupleObject*)p;
    }

    operator PyVarObject*() { return (PyVarObject*)p; }

    operator const bool() { return p != 0; }

    PyObject* Get()
    {
        return p;
    }
};

struct TextEnc
{
    // Holds encoding information for reading or writing text.  Since some drivers / databases
    // are not easy to configure efficiently, a separate instance of this structure is
    // configured for:
    //
    // * reading SQL_CHAR
    // * reading SQL_WCHAR
    // * writing unicode strings
    // * reading metadata like column names
    //
    // I would have expected the metadata to follow the SQLCHAR / SQLWCHAR based on whether the
    // ANSI or wide API was called, but it does not.

    int optenc;
    // Set to one of the OPTENC constants to indicate whether an optimized encoding is to be
    // used or a custom one.  If OPTENC_NONE, no optimized encoding is set and `name` should be
    // used.

    const char* name;
    // The name of the encoding.  This must be freed using `free`.

    SQLSMALLINT ctype;
    // The C type to use, SQL_C_CHAR or SQL_C_WCHAR.  Normally this matches the SQL type of the
    // column (SQL_C_CHAR is used for SQL_CHAR, etc.).  At least one database reports it has
    // SQL_WCHAR data even when configured for UTF-8 which is better suited for SQL_C_CHAR.

    PyObject* Encode(PyObject*) const;
    // Given a string, return a bytes object encoded.  This is used for encoding a Python
    // object for passing to a function expecting SQLCHAR* or SQLWCHAR*.
};

class SQLWChar
{
    // A convenience object that encodes a Unicode string to a given encoding.  It can be cast
    // to a SQLWCHAR* to return the pointer.
    //
    // This is designed to be created on the stack, perform the conversion, and cleanup any
    // temporary objects in the destructor.
    //
    // The SQLWCHAR pointer is *only* valid during the lifetime of this object.  It may point
    // into a temporary `bytes` object that is deleted by the constructor.

public:
    SQLWChar()
    {
        psz = 0;
        isNone = true;
    }

    SQLWChar(PyObject* src, const char* szEncoding)
    {
        psz = 0;
        isNone = true;
        set(src, szEncoding);
    }

    SQLWChar(PyObject* src, const TextEnc* penc)
    {
        init(src, *penc);
    }

    SQLWChar(PyObject* src, const TextEnc& enc)
    {
        init(src, enc);
    }

    bool isValidOrNone()
    {
        // Returns true if this object is a valid string *or* None.
        return isNone || (psz != 0);
    }

    bool isValid()
    {
        return psz != 0;
    }

    void set(PyObject* src, const char* szEncoding) {
        bytes.Attach(0);  // free old, if any
        psz = 0;
        isNone = true;

        TextEnc enc;
        enc.name = szEncoding;
        enc.ctype = SQL_C_WCHAR;
        enc.optenc = OPTENC_NONE;
        init(src, enc);
    }

    SQLWCHAR* get() { return psz; }

    operator SQLWCHAR*() { return psz; }

private:
    SQLWCHAR* psz;
    bool isNone;

    Object bytes;
    // A temporary object holding the decoded bytes if we can't use a pointer into the original
    // object.

    void init(PyObject* src, const TextEnc& enc);

    SQLWChar(const SQLWChar&) {}
    void operator=(const SQLWChar&) {}
};

struct Connection
{
    PyObject_HEAD

    // Set to SQL_NULL_HANDLE when the connection is closed.
    HDBC hdbc;

    // Will be SQL_AUTOCOMMIT_ON or SQL_AUTOCOMMIT_OFF.
    uintptr_t nAutoCommit;

    // The ODBC version the driver supports, from SQLGetInfo(DRIVER_ODBC_VER).  This is set after connecting.
    char odbc_major;
    char odbc_minor;

    // The escape character from SQLGetInfo.  This is not initialized until requested, so this may be zero!
    PyObject* searchescape;

    // Will be true if SQLDescribeParam is supported.  If false, we'll have to guess but the user will not be able
    // to insert NULLs into binary columns.
    bool supports_describeparam;

    // The column size of datetime columns, obtained from SQLGetInfo(), used to determine the datetime precision.
    int datetime_precision;

    // The connection timeout in seconds.
    long timeout;

    // Pointer connection attributes may require that the pointed-to object be kept
    // valid until some unspecified time in the future, so keep them here for now.
    PyObject* attrs_before;

    TextEnc sqlchar_enc;        // encoding used when reading SQL_CHAR data
    TextEnc sqlwchar_enc;       // encoding used when reading SQL_WCHAR data
    TextEnc unicode_enc;        // encoding used when writing unicode strings

    TextEnc metadata_enc;
    // Used when reading column names for Cursor.description.  I originally thought I could use
    // the TextEncs above based on whether I called SQLDescribeCol vs SQLDescribeColW.
    // Unfortunately it looks like PostgreSQL and MySQL (and probably others) ignore the ODBC
    // specification regarding encoding everywhere *except* in these functions - SQLDescribeCol
    // seems to always return UTF-16LE by them regardless of the connection settings.

    long maxwrite;
    // Used to override varchar_maxlength, etc.  Those are initialized from
    // SQLGetTypeInfo but some drivers (e.g. psqlodbc) return almost arbitrary
    // values (like 255 chars) leading to very slow insert performance (lots of
    // small calls to SQLPutData).  If this is zero the values from
    // SQLGetTypeInfo are used.  Otherwise this value is used.

    // These are copied from cnxn info for performance and convenience.

    int varchar_maxlength;
    int wvarchar_maxlength;
    int binary_maxlength;

    SQLLEN GetMaxLength(SQLSMALLINT ctype) const
    {
        assert(ctype == SQL_C_BINARY || ctype == SQL_C_WCHAR || ctype == SQL_C_CHAR);
        if (maxwrite != 0)
            return maxwrite;
        if (ctype == SQL_C_BINARY)
            return binary_maxlength;
        if (ctype == SQL_C_WCHAR)
            return wvarchar_maxlength;
        return varchar_maxlength;
    }

    bool need_long_data_len;

    PyObject* map_sqltype_to_converter;
    // If converters are defined, this will be a dictionary mapping from the SQLTYPE cast to an
    // int (because types can be negative) to the converter function.
    //
    // Unfortunately each lookup requires creating a Python object.  To bypass this when output
    // converters are not used, we keep this pointer null until the first converter is added,
    // which is fast to check.
};

struct ColumnInfo
{
    SQLSMALLINT sql_type;

    // The column size from SQLDescribeCol.  For character types, this is the maximum length, not including the NULL
    // terminator.  For binary values, this is the maximum length.  For numeric and decimal values, it is the defined
    // number of digits. For example, the precision of a column defined as NUMERIC(10,3) is 10.
    //
    // This value can be SQL_NO_TOTAL in which case the driver doesn't know the maximum length, such as for LONGVARCHAR
    // fields.
    SQLULEN column_size;

    // Tells us if an integer type is signed or unsigned.  This is determined after a query using SQLColAttribute.  All
    // of the integer types are the same size whether signed and unsigned, so we can allocate memory ahead of time
    // without knowing this.  We use this during the fetch when converting to a Python integer or long.
    bool is_unsigned;
};

struct ParamInfo
{
    // The following correspond to the SQLBindParameter parameters.
    SQLSMALLINT ValueType;
    SQLSMALLINT ParameterType;
    SQLULEN     ColumnSize;
    SQLSMALLINT DecimalDigits;

    // The value pointer that will be bound.  If `alloc` is true, this was allocated with malloc and must be freed.
    // Otherwise it is zero or points into memory owned by the original Python parameter.
    SQLPOINTER ParameterValuePtr;

    SQLLEN BufferLength;
    SQLLEN StrLen_or_Ind;

    // If true, the memory in ParameterValuePtr was allocated via malloc and must be freed.
    bool allocated;

    PyObject* pObject;
    // An optional object that will be decremented at the end of the execute.
    // This is useful when the ParameterValuePtr data is in a Python object -
    // the object can be put here (and INCREFed if necessary!) instead of
    // copying the data out.
    //
    // If SQLPutData is used, this must be set to a bytes or bytearray object!

    SQLLEN maxlength;
    // If SQLPutData is being used, this must be set to the amount that can be
    // written to each SQLPutData call.  (It is not clear if they are limited
    // like SQLBindParameter or not.)

    // For TVPs, the nested descriptors and current row.
    struct ParamInfo *nested;
    SQLLEN curTvpRow;

    // Optional data.  If used, ParameterValuePtr will point into this.
    union
    {
        unsigned char ch;
        int i32;
        INT64 i64;
        double dbl;
        TIMESTAMP_STRUCT timestamp;
        DATE_STRUCT date;
        TIME_STRUCT time;
    } Data;
};

struct Cursor
{
    PyObject_HEAD

    // The Connection object (which is a PyObject) that created this cursor.
    Connection* cnxn;

    // Set to SQL_NULL_HANDLE when the cursor is closed.
    HSTMT hstmt;

    //
    // SQL Parameters
    //

    // If non-zero, a pointer to the previously prepared SQL string, allowing us to skip the prepare and gathering of
    // parameter data.
    PyObject* pPreparedSQL;

    // The number of parameter markers in pPreparedSQL.  This will be zero when pPreparedSQL is zero but is set
    // immediately after preparing the SQL.
    int paramcount;

    // If non-zero, a pointer to an array of SQL type values allocated via malloc.  This is zero until we actually ask
    // for the type of parameter, which is only when a parameter is None (NULL).  At that point, the entire array is
    // allocated (length == paramcount) but all entries are set to SQL_UNKNOWN_TYPE.
    SQLSMALLINT* paramtypes;

    // If non-zero, a pointer to a buffer containing the actual parameters bound.  If pPreparedSQL is zero, this should
    // be freed using free and set to zero.
    //
    // Even if the same SQL statement is executed twice, the parameter bindings are redone from scratch since we try to
    // bind into the Python objects directly.
    ParamInfo* paramInfos;

    // Parameter set array (used with executemany)
    unsigned char *paramArray;

    // Whether to use fast executemany with parameter arrays and other optimisations
    char fastexecmany;

    // The list of information for setinputsizes().
    PyObject *inputsizes;

    //
    // Result Information
    //

    // An array of ColumnInfos, allocated via malloc.  This will be zero when closed or when there are no query
    // results.
    ColumnInfo* colinfos;

    // The description tuple described in the DB API 2.0 specification.  Set to None when there are no results.
    PyObject* description;

    int arraysize;

    // The Cursor.rowcount attribute from the DB API specification.
    int rowcount;

    // A dictionary that maps from column name (PyString) to index into the result columns (PyInteger).  This is
    // constructed during an execute and shared with each row (reference counted) to implement accessing results by
    // column name.
    //
    // This duplicates some ODBC functionality, but allows us to use Row objects after the statement is closed and
    // should use less memory than putting each column into the Row's __dict__.
    //
    // Since this is shared by Row objects, it cannot be reused.  New dictionaries are created for every execute.  This
    // will be zero whenever there are no results.
    PyObject* map_name_to_index;

    // The messages attribute described in the DB API 2.0 specification.
    // Contains a list of all non-data messages provided by the driver, retrieved using SQLGetDiagRec.
    PyObject* messages;
};

struct CnxnInfo
{
    PyObject_HEAD

    // The description of these fields is in the connection structure.

    char odbc_major;
    char odbc_minor;

    bool supports_describeparam;
    int datetime_precision;

    // Do we need to use SQL_LEN_DATA_AT_EXEC?  Some drivers (e.g. FreeTDS 0.91) have problems with long values, so
    // we'll use SQL_DATA_AT_EXEC when possible.  If this is true, however, we'll need to pass the length.
    bool need_long_data_len;

    // These are from SQLGetTypeInfo.column_size, so the char ones are in characters, not bytes.
    int varchar_maxlength;
    int wvarchar_maxlength;
    int binary_maxlength;
};

struct SQL_SS_TIME2_STRUCT
{
   SQLUSMALLINT hour;
   SQLUSMALLINT minute;
   SQLUSMALLINT second;
   SQLUINTEGER  fraction;
};

struct PYSQLGUID
{
    // I was hoping to use uint32_t, etc., but they aren't included in a Python build.  I'm not
    // going to require that the compilers supply anything beyond that.  There is PY_UINT32_T,
    // but there is no 16-bit version.  We'll stick with Microsoft's WORD and DWORD which I
    // believe the ODBC headers will have to supply.
    DWORD Data1;
    WORD Data2;
    WORD Data3;
    byte Data4[8];
};

