// Generate random bitmasks for grf and flags
unsigned int grf = *FUZZ_PARAM(unsigned int);
unsigned int flagsCandidate = *FUZZ_PARAM(unsigned int);
// Half the time, constrain flags to be a subset of grf to exercise the 'true' branch
unsigned int chooser = *FUZZ_PARAM(unsigned int);
unsigned int flags = (chooser & 1) ? (grf & flagsCandidate) : flagsCandidate;

// Compute the expected result per contract: (grf & flags) == flags
bool expected = ((grf & flags) == flags);

// Invoke target
bool rv = IsSet(grf, flags);

// Property validation: result must match bit-test identity
FUZZ_ASSERT(rv == expected, "IsSet mismatch with bit test property");

// Validation: No inputs/outputs are persistent; simple property check ensures API semantics.

// Provide a variety of argument types; they are ignored by UNUSED
int i = (int)(*FUZZ_PARAM(unsigned int));
double d = (double)(*FUZZ_PARAM(unsigned int)) / 7.0;
std::string s = FUZZ_PARAM_STR();
void* p = (void*)(uintptr_t)(*FUZZ_PARAM(unsigned int));

// Call the variadic no-op; arguments are intentionally discarded
UNUSED(i, d, s.c_str(), p);

// Validation: Safe with any arguments; no persistent objects or side effects.

// Prepare a safe, matching printf-style invocation
std::string msg = FUZZ_PARAM_STR();
unsigned int u = *FUZZ_PARAM(unsigned int);
unsigned long long ull = (unsigned long long)(*FUZZ_PARAM(unsigned int));

// Use format specifiers that exactly match the provided arguments
// When tracing is disabled this becomes a no-op; when enabled it must be type-correct
DebugTrace("%s %u %llu", msg.c_str(), u, ull);

// Validation: Arguments and format specifiers match; no reliance on side effects.

// Start with a null BYTE* per contract; allocate, possibly reallocate, and free
BYTE* buf = 0;

// First allocation size in [0, 1024]
size_t n1 = (size_t)(*FUZZ_PARAM(unsigned int) % 1025);
BYTE* old1 = buf;
bool ok1 = PyMem_Realloc(&buf, n1);
if (!ok1) {
    // On failure, pointer must remain unchanged
    FUZZ_ASSERT(buf == old1, "PyMem_Realloc changed pointer on failure (step 1)");
} else {
    // On success, if size > 0 the returned pointer should be non-null
    if (n1 > 0 && buf == 0) { FUZZ_BAIL(); }
    // Touch first/last bytes when size > 0 to validate readability/writability
    if (n1 > 0) {
        buf[0] = (BYTE)(*FUZZ_PARAM(unsigned int));
        buf[n1 - 1] = (BYTE)(*FUZZ_PARAM(unsigned int));
    }
}

// Second resize in [0, 2048]
size_t n2 = (size_t)(*FUZZ_PARAM(unsigned int) % 2049);
BYTE* old2 = buf;
bool ok2 = PyMem_Realloc(&buf, n2);
if (!ok2) {
    FUZZ_ASSERT(buf == old2, "PyMem_Realloc changed pointer on failure (step 2)");
} else {
    if (n2 > 0 && buf == 0) { FUZZ_BAIL(); }
    if (n2 > 0) {
        buf[0] = (BYTE)(*FUZZ_PARAM(unsigned int));
        buf[n2 - 1] = (BYTE)(*FUZZ_PARAM(unsigned int));
    }
}

// Cleanup: caller is responsible for freeing the final pointer
if (buf) { free(buf); buf = 0; }

// Validation: Pointer-stability on failure is asserted; successful allocations are exercised and freed.

// Generate a buffer and a safe length
std::string data = FUZZ_PARAM_STR();
size_t len = data.size();
// Optionally shrink length to a subrange to increase path coverage
if (len > 0) {
    size_t sub = (size_t)(*FUZZ_PARAM(unsigned int) % (len + 1));
    len = sub;
}

// If len == 0, passing nullptr is permitted by contract; otherwise pass a readable region
void* p = (len == 0) ? (void*)0 : (void*)data.data();
PrintBytes(p, len);

// Validation: Ensures p is null only when len == 0; otherwise points to readable memory.

// Provide a random SQLSMALLINT code
SQLSMALLINT code = (SQLSMALLINT)(*FUZZ_PARAM(unsigned int));
const char* name = CTypeName(code);
// Contract: returned pointer refers to internal storage and should be non-null
FUZZ_ASSERT(name != 0, "CTypeName returned null");
UNUSED(name);

// Validation: Simple non-null property; no ownership or outputs.

// Provide a random SQLSMALLINT code
SQLSMALLINT code = (SQLSMALLINT)(*FUZZ_PARAM(unsigned int));
const char* name = SqlTypeName(code);
// Contract: returned pointer refers to internal storage and should be non-null
FUZZ_ASSERT(name != 0, "SqlTypeName returned null");
UNUSED(name);

// Validation: Simple non-null property; no ownership or outputs.

// Construct an Object from a possibly-null owned PyObject*.
// Enforce: if we pass a non-null PyObject*, it must be an owned reference so that Object can DECREF it later.
unsigned int choose_null = *FUZZ_PARAM(unsigned int);
PyObject* init_ptr = (choose_null % 2 == 0) ? (PyObject*)0 : py;
if (init_ptr != 0) {
    int owned = FUZZ_GET_ATTR_INT(py, "owned");
    if (!owned) { FUZZ_BAIL(); }
}
// Allocate on heap so the runtime can manage as a persistent output object.
Object* obj = new Object(init_ptr);
// Track the ownership transfer if non-null was provided.
if (init_ptr != 0) {
    FUZZ_SET_ATTR_PTR(obj, "py", init_ptr);
    FUZZ_SET_ATTR_INT(obj, "owns_py", 1);
    // Ownership moved into Object; mark the input as no longer owned by the pool to avoid double DECREF by other stubs.
    FUZZ_SET_ATTR_INT(py, "owned", 0);
} else {
    FUZZ_SET_ATTR_PTR(obj, "py", (void*)0);
    FUZZ_SET_ATTR_INT(obj, "owns_py", 0);
}
// Output: obj remains live for future stubs.

// Invoke the destructor by deleting the heap-allocated Object.
// Requirement: If obj still holds a non-null PyObject*, it must be valid for Py_XDECREF; prior stubs enforced ownership.
// Optionally clear attributes before delete to reduce reuse of stale metadata.
void* held = FUZZ_GET_ATTR_PTR(obj, "py");
FUZZ_SET_ATTR_PTR(obj, "py", (void*)0);
FUZZ_SET_ATTR_INT(obj, "owns_py", 0);
// We cannot guarantee the fate of the held PyObject* after DECREF, so we do not return it.
// Perform deletion (triggers ~Object which will Py_XDECREF if needed).
delete obj;
// No outputs; the object is destroyed.

// Assign a new PyObject* to the wrapper, DECREFing any previously held pointer.
// Enforce pNew constraints if we choose to pass it (may also pass null).
unsigned int choose_null = *FUZZ_PARAM(unsigned int);
PyObject* arg = (choose_null % 2 == 0) ? (PyObject*)0 : pNew;
if (arg != 0) {
    int owned = FUZZ_GET_ATTR_INT(pNew, "owned");
    if (!owned) { FUZZ_BAIL(); }
}
// Perform the assignment; this will DECREF any currently held pointer.
(*obj) = arg;
// Update metadata: track currently held pointer and ownership state within the Object.
FUZZ_SET_ATTR_PTR(obj, "py", (void*)arg);
FUZZ_SET_ATTR_INT(obj, "owns_py", arg != 0 ? 1 : 0);
// Ownership of pNew transferred into obj if non-null: mark input as no longer owned by the pool.
if (arg != 0) {
    FUZZ_SET_ATTR_INT(pNew, "owned", 0);
}
// Output the mutated obj for continued lifetime.

// Call IsValid; no ownership mutation occurs.
bool valid = obj->IsValid();
// Cross-check against tracked metadata when available.
void* tracked = FUZZ_GET_ATTR_PTR(obj, "py");
if (tracked != 0 || FUZZ_GET_ATTR_INT(obj, "owns_py") != 0) {
    // If we have any tracked pointer information, then validity should agree with whether tracked != 0.
    FUZZ_ASSERT(valid == (tracked != 0), "Object::IsValid should reflect whether internal pointer is non-null");
}
// Return obj to pool.

// Replace the wrapped pointer with _p, DECREFing any previously held pointer. Does not INCREF _p.
// Enforce: if _p is non-null it must be an owned reference so the Object can later DECREF it.
unsigned int choose_null = *FUZZ_PARAM(unsigned int);
PyObject* arg = (choose_null % 2 == 0) ? (PyObject*)0 : _p;
if (arg != 0) {
    int owned = FUZZ_GET_ATTR_INT(_p, "owned");
    if (!owned) { FUZZ_BAIL(); }
}
bool ret = obj->Attach(arg);
// ret indicates arg != 0; validate that contract.
FUZZ_ASSERT(ret == (arg != 0), "Attach should return true iff new pointer is non-null");
// Update metadata and transfer ownership if applicable.
FUZZ_SET_ATTR_PTR(obj, "py", (void*)arg);
FUZZ_SET_ATTR_INT(obj, "owns_py", arg != 0 ? 1 : 0);
if (arg != 0) {
    FUZZ_SET_ATTR_INT(_p, "owned", 0);
}
// Output mutated obj.

// Detach releases ownership without DECREF and returns the raw pointer.
PyObject* py_out = obj->Detach();
// After detach, Object should be invalid until reassigned; update attributes accordingly.
FUZZ_SET_ATTR_PTR(obj, "py", (void*)0);
FUZZ_SET_ATTR_INT(obj, "owns_py", 0);
// The returned pointer, if non-null, is now owned by the caller; mark as owned for the pool.
if (py_out != 0) {
    FUZZ_SET_ATTR_INT(py_out, "owned", 1);
} else {
    // Ensure outputs are never null per harness rules: if null, bail because nothing meaningful to return.
    FUZZ_BAIL();
}
// Return both the now-empty obj and the detached owned PyObject*.

// Implicit conversion to PyObject*; no ownership changes.
PyObject* p = (PyObject*)(*obj);
// If we have tracked metadata, ensure consistency with Get().
void* tracked = FUZZ_GET_ATTR_PTR(obj, "py");
if (tracked != 0 || FUZZ_GET_ATTR_INT(obj, "owns_py") != 0) {
    FUZZ_ASSERT(p == (PyObject*)tracked, "operator PyObject* should return the wrapped pointer");
}
// Do not output p as it is a borrowed/raw pointer and may not be owned.
// Return obj to keep it live.

// Implicit conversion to PyTupleObject*. Safe to obtain and discard without using it.
PyTupleObject* tp = (PyTupleObject*)(*obj);
// We do not dereference or DECREF it. No ownership changes.
(void)tp;
// Keep obj as output.

// Implicit conversion to PyVarObject*. Safe to obtain and discard without using it.
PyVarObject* vp = (PyVarObject*)(*obj);
(void)vp;
// Keep obj as output.

// Implicit conversion to bool indicates whether the wrapped pointer is non-null.
bool b = (const bool)(*obj);
void* tracked = FUZZ_GET_ATTR_PTR(obj, "py");
if (tracked != 0 || FUZZ_GET_ATTR_INT(obj, "owns_py") != 0) {
    FUZZ_ASSERT(b == (tracked != 0), "operator bool should reflect whether internal pointer is non-null");
}
// Return obj to pool.

// Returns the raw wrapped PyObject*; no ownership changes.
PyObject* p = obj->Get();
// Validate against tracked metadata when present.
void* tracked = FUZZ_GET_ATTR_PTR(obj, "py");
if (tracked != 0 || FUZZ_GET_ATTR_INT(obj, "owns_py") != 0) {
    FUZZ_ASSERT(p == (PyObject*)tracked, "Get should return the wrapped pointer");
}
// Do not output p; keep obj as output.

// Construct a heap-allocated SQLWChar so the object can persist across stubs.
SQLWChar *sqlw = new SQLWChar();

// Track initial invariants from the default constructor for downstream checks.
// Default ctor sets psz=null and isNone=true, so isValidOrNone() should be true and isValid() false.
FUZZ_SET_ATTR_INT(sqlw, "is_none", 1);
FUZZ_SET_ATTR_INT(sqlw, "has_buf", 0);

// Validation: This stub creates a valid, persistent SQLWChar instance without invoking any Python APIs.
// The object is returned to the pool for later use.

// Call the query method; it has no side effects on the object state.
bool ok = sqlw->isValidOrNone();

// Record the result for downstream stubs to make decisions without re-checking.
FUZZ_SET_ATTR_INT(sqlw, "is_valid_or_none", ok ? 1 : 0);

// Validation: The method is safe to call without CPython state. We persist sqlw for future use.

// Query validity (non-null wide-char pointer present?).
bool valid = sqlw->isValid();

// Track as attribute for later stubs that must guard pointer access.
FUZZ_SET_ATTR_INT(sqlw, "is_valid", valid ? 1 : 0);

// Validation: Read-only query; no Python interaction. We return sqlw unchanged.

// Per API contract, only "use" the returned pointer if the object is valid.
// We still may call get(), but we won't dereference unless valid.
