import random
import string
from typing import List, Tuple

# Generator for valid decimal text buffers suitable for DecimalFromText(enc, pb, cb)
# The fuzzer stub sometimes sets enc.ctype to either SQL_C_CHAR or SQL_C_WCHAR (represented as 1 or 2).
# We only provide the raw bytes buffer; the stub converts std::string to byte*.
# Our goal is to return bytes that represent a valid decimal string under common decimal point settings.
# We will prefer ASCII digits with '.' as decimal separator, optionally include sign, underscores not used.
# We will also sometimes include locale-style ',' separator to exercise failure/success depending on decimal point,
# but keep most cases valid by using '.'

MAX_LEN = 4096

DECIMAL_SEPARATORS = ['.', ',']


def _rand_digits(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    # Avoid leading zeros unless explicitly generating zero
    if n == 0:
        return ""
    if n == 1:
        return str(rng.randint(0, 9))
    first = str(rng.randint(1, 9))
    rest = ''.join(str(rng.randint(0, 9)) for _ in range(n - 1))
    return first + rest


def _gen_simple_decimal(rng: random.Random) -> str:
    # Pattern: [sign] integer [sep fractional] with optional exponent trimmed (avoid since not guaranteed supported)
    sign = '-' if rng.random() < 0.3 else ''
    # Sometimes zero integer part
    if rng.random() < 0.2:
        int_part = '0'
    else:
        int_part = _rand_digits(rng, 1, 18)
    if rng.random() < 0.6:
        # include fractional part
        sep = '.'  # favor '.' for higher validity
        # Occasionally use ',' but much rarer
        if rng.random() < 0.05:
            sep = ','
        frac_len = rng.randint(0, 18)
        frac = ''.join(str(rng.randint(0, 9)) for _ in range(frac_len))
        # Ensure at least one digit after separator to be a proper decimal fraction
        if frac_len == 0:
            frac = '0'
        return f"{sign}{int_part}{sep}{frac}"
    else:
        return f"{sign}{int_part}"


def _gen_leading_trailing_spaces(rng: random.Random, s: str) -> str:
    # Many parsers tolerate surrounding whitespace
    left = ' ' * rng.randint(0, 3)
    right = ' ' * rng.randint(0, 3)
    return left + s + right


def _gen_plus_sign(rng: random.Random, s: str) -> str:
    if s and s[0] not in '+-':
        if rng.random() < 0.2:
            return '+' + s
    return s


def _gen_scale_variants(rng: random.Random) -> str:
    # Create numbers with varying scales and sizes, including large integers and many fractional digits
    sign = '-' if rng.random() < 0.25 else ''
    # choose magnitude length skewed toward small but sometimes large
    choices = [rng.randint(1, 9)] * 5 + [rng.randint(10, 40)] * 2 + [rng.randint(41, 200)]
    int_len = rng.choice(choices)
    int_part = ''.join(str(rng.randint(0, 9)) for _ in range(int_len))
    if int_part[0] == '0' and int_len > 1:
        int_part = '1' + int_part[1:]
    if rng.random() < 0.7:
        frac_len = rng.choice([0, 1, 2, 3, 6, 9, 12, 18, rng.randint(1, 64)])
        frac = ''.join(str(rng.randint(0, 9)) for _ in range(frac_len))
        if frac_len == 0:
            return f"{sign}{int_part}"
        return f"{sign}{int_part}.{frac}"
    else:
        return f"{sign}{int_part}"


def _gen_zero_edge_cases(rng: random.Random) -> List[str]:
    # Numbers that are edge-y but valid
    cases = [
        '0', '0.0', '-0', '-0.0', '+0', '+0.000', '0.' + '0' * rng.randint(1, 20)
    ]
    return cases


def _maybe_wide_encoding(rng: random.Random, s: str) -> bytes:
    # The stub may set enc.ctype to wide; however, TextEnc.name is None and optenc is 0.
    # The callee interprets bytes according to enc. We only control pb/cb.
    # We will primarily emit UTF-8 bytes since std::string is used; the function will treat bytes as provided.
    # To exercise wide paths, sometimes interleave NUL bytes (UTF-16LE ASCII) if length allows.
    if rng.random() < 0.1:
        # Encode as UTF-16LE without BOM to simulate wide-char buffer content
        return s.encode('utf-16le')
    else:
        return s.encode('utf-8')


def _compose_valid_decimal_bytes(rng: random.Random) -> bytes:
    # Choose a strategy
    p = rng.random()
    if p < 0.35:
        s = _gen_simple_decimal(rng)
    elif p < 0.7:
        s = _gen_scale_variants(rng)
    else:
        s = rng.choice(_gen_zero_edge_cases(rng))
    # Optional decorations
    if rng.random() < 0.6:
        s = _gen_plus_sign(rng, s)
    if rng.random() < 0.6:
        s = _gen_leading_trailing_spaces(rng, s)
    b = _maybe_wide_encoding(rng, s)
    if len(b) > MAX_LEN:
        b = b[:MAX_LEN]
    return b


def _compose_empty_or_minimal(rng: random.Random) -> bytes:
    # Sometimes return empty buffer (pb == nullptr, cb == 0 will be simulated by stub if string is empty)
    # But we cannot return None; we return empty bytes which results in cb=0 and pb pointer to empty string data.
    # The stub special-cases empty by setting pb=null; still acceptable to provide empty.
    return b""


def _compose_locale_variant(rng: random.Random) -> bytes:
    # Use comma as decimal separator to exercise decimal point settings. Surround with spaces optionally.
    sign = ''
    if rng.random() < 0.5:
        sign = rng.choice(['', '+', '-'])
    int_part = _rand_digits(rng, 1, 8)
    frac = ''.join(str(rng.randint(0, 9)) for _ in range(rng.randint(1, 8)))
    s = f"{sign}{int_part},{frac}"
    if rng.random() < 0.5:
        s = _gen_leading_trailing_spaces(rng, s)
    b = _maybe_wide_encoding(rng, s)
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide among modes similar to fuzzer stub's branches, but bias toward valid decimals
    mode = rng.randint(0, 99)
    if mode < 10:
        return _compose_empty_or_minimal(rng)
    elif mode < 20:
        return _compose_locale_variant(rng)
    else:
        return _compose_valid_decimal_bytes(rng)
